INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13131, 'koKR', 'Śmieci w mym kufrze', 'No popatrz tylko! Mój kufer jeszcze nigdy nie był taki pusty. Powinien być już dziesięć razy pełny!$b$bMoi kamraci rzucili się na widok tych wszystkich łupów i patrz, co z nich zostało! Grzechoczące kości, ot co!$b$bJak to mawiała moja matula: gorsze od braku skarbu jest tylko przeklęte złoto.$b$bAle słuchaj no, dalej w środku jest pełno łupów, i założę się, że nie tych przeklętych. Tym moczymordom na nic się nie przydadzą – dla nich to tylko śmieci.$b$bPrzynieś mi je, a sowicie cię wynagrodzę, kamracie.$B', 'Brigg na Iglicy Utgard chce, żebyś $gznalazł:znalazła; 5 niezmatowiałych sztabek srebra, 3 błyszczące błyskotki, 2 złote puchary i nefrytowy posąg.', '', 'Wróć do Brigga Krótkonogiego na Iglicy Utgard.', '', '', '', '', 0),
(13132, 'koKR', 'Zemsta będzie moja!', 'Och! Nie można ich winić, $gchłopcze:dziewczyno;. Kto by postąpił inaczej?$b$bRzucili się na te sterty złota – myśleli, że trafili na żyłę złota, ot co. Tak... Ale spójrz na nich teraz. Bezmyślne sługi, co nie podniosą nawet jednego dublona.$b$bTylko szczęście uchroniło mnie przed tym samym losem. W tej bieganinie ktoś mnie przewrócił – a byłem już trochę wstawiony. Podniosłem wzrok i zobaczyłem, jak pierwszy z nich się przemienia...$b$bBądź $gdobrym chłopcem:dobrą dziewczyną;, znajdź tego, kto tu rządzi, i oducz go rzucania klątw na moich kamratów.', 'Brigg na Iglicy Utgard chce, żebyś $gzabił:zabiła; króla Ymirona.', '', 'Wróć do Brigga Krótkonogiego na Iglicy Utgard.', 'Zabity król Ymiron', '', '', '', 0),
(13241, 'koKR', 'Timear widzi w twojej przyszłości Berserkerów Ymirjarów!', 'W niedalekiej przyszłości między tobą a zwycięstwem staną czempioni króla Ymirona.$B$BUdasz się do twierdzy zwanej Iglicą Utgard, ukrytej głęboko w lasach Wyjącego Fiordu. Nie potrafię dość mocno podkreślić, jak ważne jest, byś ty i twoi towarzysze podróży rozprawili się z berserkerami Ymirjarów, którzy tam przebywają.$B$BJeśli tego nie zrobicie, może to oznaczać twoją zgubę, $N!', 'Arcymag Timear w Dalaranie chce, żebyś $gzabił:zabiła; 7 berserkerów Ymirjarów.', '', '', '', '', '', '', 0),
(13248, 'koKR', 'Dowód zgonu: Król Ymiron', 'Król Ymiron z Iglicy Utgard jest ulubionym wrykulem Króla Lisza. Już samo to wystarczy, by z nim skończyć.$B$BLecz jeśli zadmie w rogi i wezwie wszystkich przywódców zarówno Ymirjarów, jak i Mjordinów, wrykule staną się potęgą większą niż jakakolwiek inna w szeregach Plagi!$B$BTo od ciebie, $N, zależy, czy do tego nie dojdzie. Przynieś mi medalion z jego szyi, żebym wiedział, że Ymiron nie stanowi już zagrożenia.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Medalionem zmarłej królowej.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13131, 'koKR', 'Wspaniale! Udało ci się, kamracie.$b$bTeraz mogę się pokazać kapitanowi bez strachu o własną skórę, a wszystko dzięki tobie i twoim kompanom.$b$bMasz tu trochę łupów w podzięce.', 0),
(13132, 'koKR', 'Wyśmienicie! Może teraz moi kamraci zaznają spokoju.$b$bProszę bardzo, $gchłopcze:dziewczyno;. Niech nikt nie mówi, że stary Brigg nie był hojny dla tych, co okazali mu dobroć.$b$bDobrze się z tobą robi interesy.', 0),
(13241, 'koKR', 'Znakomita robota, $N.$b$bGdyby nie to, ocalali berserkerzy z pewnością rzuciliby się na ciebie całą chmarą podczas walki z królem.', 0),
(13248, 'koKR', '<Arcymag posępnie kiwa głową, gdy podajesz mu tę dość dużą błyskotkę.>$b$bCo się stało, to się nie odstanie. Jakże szlachetna to rasa, ci wrykule. Szkoda, że Król Lisz wbił w nich swoje śmiercionośne szpony.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13131, 'koKR', 'Jak ci poszło, $gkamracie:kamratko;?', 0),
(13132, 'koKR', '$GZnalazłeś:Znalazłaś; tego, kto tu rządzi? $GDałeś:Dałaś; mu popalić?', 0),
(13241, 'koKR', '<Arcymag przykłada palce do skroni i się koncentruje.>$B$BBerserkerzy wciąż żyją. Posłuchaj mojego ostrzeżenia, $N. Musisz to zrobić!', 0),
(13248, 'koKR', 'Nie wolno pozwolić, by Ymiron zjednoczył naród wrykulów. Jeśli wróci triumfalnie do Lodowej Korony, najpewniej wszystko będzie stracone.', 0);
