INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27809, 'koKR', 'Skadi Bezwzględny jest w zasięgu wyrzutni harpunów!', '', 0),
(29684, 'koKR', '', 'Mój panie! Uczyniłam, o co prosiłeś, a teraz błagam cię o błogosławieństwo!', 0),
(31447, 'koKR', 'Co to za miejsce? Zniszczę was!', '', 0),
(31452, 'koKR', 'Ty zginąć! Tego chcieć pan.', '', 0),
(31453, 'koKR', 'Łatwe zadanie!', '', 0),
(31454, 'koKR', 'Jakie kundle śmią tu wtargnąć? Żwawo, bracia! Uczta dla tego, kto przyniesie mi ich głowy!', '', 0),
(31459, 'koKR', 'Wy łajdacy bez matek! Wasze truchła będą wybornymi kąskami dla mojego nowego smoka!', '', 0),
(31461, 'koKR', 'Już nie taki zuchwały, co?', '', 0),
(31462, 'koKR', 'Zatknę twoją czaszkę na najwyższej wieży!\n', '', 0),
(31463, 'koKR', 'ARGH! To ma być... atak? Ja wam... pokażę... aghhhh...', '', 0),
(31464, 'koKR', 'Najeżdżacie mój dom, a potem śmiecie rzucać mi wyzwanie? Wyrwę wam serca z piersi i złożę je w darze bogu śmierci! Rualg nja gaborr!', '', 0),
(31465, 'koKR', 'Bjornie z Czarnej Burzy! Zaszczyć mnie teraz swoją obecnością!', '', 0),
(31466, 'koKR', 'Haldorze ze Skalistych Urwisk! Użycz mi swojej siły!', '', 0),
(31467, 'koKR', 'Ranulfie z Wyjącej Otchłani! Zgaś te robaki najczarniejszą nocą!', '', 0),
(31468, 'koKR', 'Torze od Brutalnego Oblężenia, obdarz mnie swoją potęgą!', '', 0),
(31469, 'koKR', 'Wasza śmierć to dopiero początek.', '', 0),
(31470, 'koKR', 'Zawiedliście swój lud!\n', '', 0),
(31471, 'koKR', 'Nie bez powodu to ja jestem królem!\n', '', 0),
(31473, 'koKR', 'Co... czeka mnie... teraz?', '', 0),
(31520, 'koKR', '<hik>$b$bSamotnie tu bez moich kamratów, $gchłopcze:dziewczyno;.', '', 0),
(31521, 'koKR', 'Jarr! Ktoś musi pokazać tym łachudrom, gdzie raki zimują!$b$b<hik>', '', 0),
(31522, 'koKR', 'Czas skopać parę tyłków i napić się podwójnego rumu!$b$bA podwójnego rumu prawie mi już brak...', '', 0);
